using Dapper;using Microsoft.Extensions.Diagnostics.HealthChecks;using MySqlConnector;
namespace Commerce.Operations.Api.Operations;
public sealed class DependencyHealthCheck(IConfiguration configuration,IHttpClientFactory clients):IHealthCheck{public async Task<HealthCheckResult> CheckHealthAsync(HealthCheckContext context,CancellationToken token=default){try{await using var connection=new MySqlConnection(configuration.GetConnectionString("Operations"));await connection.ExecuteScalarAsync<int>(new CommandDefinition("SELECT 1",cancellationToken:token));using var response=await clients.CreateClient("order-engine-health").GetAsync("/actuator/health",token);if(!response.IsSuccessStatusCode)return HealthCheckResult.Unhealthy("Order engine is not ready.");return HealthCheckResult.Healthy("MySQL and order engine are ready.");}catch(Exception exception){return HealthCheckResult.Unhealthy("A required dependency is unavailable.",exception);}}}
